  handle_result, error_remark, start_time, 
  end_time, host_ip, create_time
  )
values (#{optimistic,jdbcType=INTEGER}, #{cronKey,jdbcType=VARCHAR}, #{ableStatus,jdbcType=VARCHAR}, 
  #{handleResult,jdbcType=VARCHAR}, #{errorRemark,jdbcType=VARCHAR}, #{startTime,jdbcType=TIMESTAMP}, 
