select


from scheduled_task_log
where 1=1

  and optimistic = #{optimistic,jdbcType=INTEGER}


  and cron_key = #{cronKey,jdbcType=VARCHAR}


  and able_status = #{ableStatus,jdbcType=VARCHAR}


  and handle_result = #{handleResult,jdbcType=VARCHAR}


  and error_remark = #{errorRemark,jdbcType=VARCHAR}


  and start_time = #{startTime,jdbcType=TIMESTAMP}


  and end_time = #{endTime,jdbcType=TIMESTAMP}


  and host_ip = #{hostIp,jdbcType=VARCHAR}


  and create_time = #{createTime,jdbcType=TIMESTAMP}

order by create_time desc
